<?php require_once __DIR__.'/lib/inicio.php';exigir_sesion();$c=obtener_caso((int)($_GET['id']??0));$fases=['Registro','Clasificación','Planeación','Campo y encuestas'];if(requiere_actualizacion_externa($c['tipo_caso']))$fases[]='Actualización externa';$fases=array_merge($fases,['Propuesta','Revisión','Cierre']);include 'encabezado.php';?><section class="tarjeta"><h1><?=h($c['folio'])?></h1><p><b><?=h($c['clave_ut'].' '.$c['nombre_ut'])?></b> · <?=h($c['nombre_demarcacion'])?> · <span class="etiqueta"><?=h(etiqueta_estado($c['estado']))?></span></p><div class="avances"><?php foreach($fases as $i=>$f):$n=$i+1;?><div class="fase <?=$n<$c['fase_actual']?'terminada':($n==$c['fase_actual']?'actual':'')?>"><?=$n?>. <?=h($f)?></div><?php endforeach?></div><div class="acciones"><a class="boton gris" href="acuse.php?id=<?=$c['id_caso']?>">Acuse PDF</a><a class="boton gris" href="ficha.php?id=<?=$c['id_caso']?>">Ficha técnica PDF</a><a class="boton secundario" href="archivos.php?id=<?=$c['id_caso']?>">Archivos</a><?php if(es_control()):?><a class="boton verde" href="exportar.php?id=<?=$c['id_caso']?>">Expediente ZIP</a><?php endif?></div></section><section class="tarjeta"><h2>Continuar proceso</h2><?php if($c['estado']==='REGISTRADO'):?><a class="boton" href="fase.php?id=<?=$c['id_caso']?>&fase=2">Clasificar caso</a><?php elseif($c['estado']==='CLASIFICADO'):?><a class="boton" href="fase.php?id=<?=$c['id_caso']?>&fase=3">Registrar planeación</a><?php elseif($c['estado']==='PLANEACION_COMPLETA'):?><a class="boton" href="fase.php?id=<?=$c['id_caso']?>&fase=4">Campo y encuestas</a><?php elseif($c['estado']==='CAMPO_COMPLETO'&&requiere_actualizacion_externa($c['tipo_caso'])):?><a class="boton" href="fase.php?id=<?=$c['id_caso']?>&fase=5">Actualización externa</a><?php elseif(in_array($c['estado'],['CAMPO_COMPLETO','ACTUALIZACION_EXTERNA_COMPLETA'],true)):?><a class="boton" href="fase.php?id=<?=$c['id_caso']?>&fase=6">Integrar propuesta</a><?php elseif($c['estado']==='PROPUESTA_COMPLETA'&&es_control()):?><a class="boton" href="fase.php?id=<?=$c['id_caso']?>&fase=7">Revisión técnica</a><?php elseif($c['estado']==='EN_REVISION'):?><a class="boton" href="fase.php?id=<?=$c['id_caso']?>&fase=8">Cerrar expediente</a><?php else:?><p>No hay una fase disponible para el perfil actual.</p><?php endif?></section><section class="tarjeta"><h2>Datos del caso</h2><div class="rejilla"><p><b>Solicitante:</b><br><?=h($c['nombre_solicitante'])?></p><p><b>Tipo:</b><br><?=h($c['tipo_caso']?:'Pendiente')?></p><p><b>Secciones C:</b><br><?=h($c['secciones_c'])?></p><p><b>Secciones P:</b><br><?=h($c['secciones_p'])?></p></div><p><b>Solicitud:</b><br><?=nl2br(h($c['descripcion_solicitud']))?></p></section><?php include 'pie.php';?>